        $generateLargeMatrix = function ($rows, $cols) {
            $matrix = [];
            $rowNames = ['A','B','C','D','E','F','G','H','I','J','K','L'];
            for ($r = 0; $r < min($rows, count($rowNames)); $r++) {
                $rName = $rowNames[$r];
                for ($c = 1; $c <= $cols; $c++) {
                    $type = ($r >= 3 && $r <= 7) ? 'VIP' : (($r >= 8) ? 'COUPLE' : 'STANDARD');
                    $matrix[] = [
                        'seat_id' => $rName . $c,
                        'row_name' => $rName,
                        'seat_number' => (string)$c,
                        'type' => $type,
                        'cx' => $c * 38,
                        'cy' => ($r + 1) * 38,
                        'angle' => 0,
                    ];
                }
            }
            return $matrix;
        };

